use std::env;
use std::fs;
use std::path::PathBuf;
use std::process;
use std::io::{self, Read, Write};
use std::time::SystemTime;

mod args;
mod calendar;
mod ical;
mod data;
mod format;

use args::Args;
use calendar::{Appointment, Event, Todo};
use data::DataStore;

const VERSION: &str = "4.8.2";
const USAGE: &str = r#"Usage:
calcurse [-D <directory>] [-C <directory>] [-c <calendar file>]
calcurse -Q [--from <date>] [--to <date>] [--days <number>]
calcurse -a | -d <date> | -d <number> | -n | -r[<number>] | -s[<date>] | -t[<number>]
calcurse -h | -v | --status | -G | -P | -g | -i <file> | -x[<format>] | --daemon

Operations in command line mode:
  -Q, --query   Print items in a given query range
  -G, --grep    Grep items from the data files
  -P, --purge   Read items and write them back
Query short forms:
-a, -d <date>|<number>, -n, -r[<number>], -s[<date>], -t<number>

Note that filter, format and day-range options affect input or output:
  --filter-*              Filter items loaded by -Q, -G, -P and -x
  --format-*              Rewrite output from -Q, -G and --dump-imported
  --from <date>           Limit day range of -Q.
  --to <date>             Limit day range of -Q.
  --days <number>         Limit day range of -Q.

  --limit, -l <number>    Limit number of query results
  --search, -S <regexp>   Match regular expression in queries
Consult the man page for details.

Miscellaneous:
  -c, --calendar <file>   The calendar data file to use
  -C, --confdir <dir>     The configuration directory to use
  --daemon                Run notification daemon in the background
  -D, --datadir <dir>     The data directory to use
  -g, --gc                Run the garbage collector
  -h, --help              Show this help text
  -i, --import <file>     Import iCal data from file
  -q, --quiet             Suppress import/export result message
  --read-only             Do not save configuration or data files
  --status                Display status of running instances
  -v, --version           Show version information
  -x, --export[<format>]  Export to stdout in ical (default) or pcal format

For more information, type '?' from within calcurse, or read the manpage.
Submit feature requests and suggestions to <misc@calcurse.org>.
Submit bug reports to <bugs@calcurse.org>."#;

fn main() {
    let args = args::parse_args(env::args().collect());

    if args.help {
        println!("{}", USAGE);
        process::exit(0);
    }

    if args.version {
        println!("calcurse {} -- text-based organizer\n", VERSION);
        println!("Copyright (c) 2004-2023 calcurse Development Team.");
        println!("This is free software; see the source for copying conditions.");
        process::exit(0);
    }

    // Determine data directory
    let data_dir = if let Some(ref dir) = args.datadir {
        PathBuf::from(dir)
    } else if let Some(ref dir) = args.calendar_file {
        PathBuf::from(dir).parent().unwrap_or_else(|| std::path::Path::new(".")).to_path_buf()
    } else {
        let home = env::var("HOME").unwrap_or_else(|_| ".".to_string());
        PathBuf::from(home).join(".calcurse")
    };

    // Load or initialize data store
    let mut data_store = DataStore::new(data_dir.clone());

    if args.import.is_some() {
        handle_import(&args, &mut data_store);
    } else if args.export {
        handle_export(&args, &data_store);
    } else if args.query {
        handle_query(&args, &data_store);
    } else if args.grep {
        handle_grep(&args, &data_store);
    } else if args.appointments {
        handle_appointments(&args, &data_store);
    } else if args.next {
        handle_next(&args, &data_store);
    } else if args.todo {
        handle_todo(&args, &data_store);
    } else if args.day.is_some() {
        handle_day(&args, &data_store);
    } else if args.gc {
        handle_gc(&args, &data_store);
    } else if args.status {
        handle_status();
    } else if args.daemon {
        handle_daemon();
    } else if args.purge {
        handle_purge(&args, &mut data_store);
    } else {
        // Interactive mode
        eprintln!("Error opening terminal: unknown.");
        process::exit(1);
    }
}

fn handle_import(args: &Args, data_store: &mut DataStore) {
    if let Some(ref file) = args.import {
        let mut contents = String::new();
        if fs::File::open(file)
            .and_then(|mut f| f.read_to_string(&mut contents))
            .is_err()
        {
            eprintln!("Error opening file: {}", file);
            process::exit(1);
        }

        let (apps, events, todos, skipped) = ical::parse_ical(&contents);

        data_store.add_appointments(&apps);
        data_store.add_events(&events);
        data_store.add_todos(&todos);

        if !args.read_only {
            data_store.save().ok();
        }

        if !args.quiet {
            let total_lines = contents.lines().count();
            println!("Import process report: {:04} lines read", total_lines);
            println!("{} app / {} events / {} todo / {} skipped", 
                apps.len(), events.len(), todos.len(), skipped);
        }
    }
}

fn handle_export(args: &Args, data_store: &DataStore) {
    let format = if let Some(ref fmt) = args.export_format {
        fmt.as_str()
    } else {
        "ical"
    };

    match format {
        "pcal" => {
            data_store.export_pcal();
        }
        _ => {
            data_store.export_ical();
        }
    }
}

fn handle_query(args: &Args, data_store: &DataStore) {
    data_store.query(&args);
}

fn handle_grep(args: &Args, data_store: &DataStore) {
    data_store.grep(&args);
}

fn handle_appointments(args: &Args, data_store: &DataStore) {
    data_store.list_appointments(&args);
}

fn handle_next(_args: &Args, data_store: &DataStore) {
    data_store.list_next();
}

fn handle_todo(args: &Args, data_store: &DataStore) {
    data_store.list_todos(&args);
}

fn handle_day(args: &Args, data_store: &DataStore) {
    data_store.list_day(&args);
}

fn handle_gc(_args: &Args, _data_store: &DataStore) {
    // Garbage collection - nothing for now
}

fn handle_status() {
    println!("calcurse is running (pid {})", process::id());
}

fn handle_daemon() {
    // Daemon mode - not implemented
}

fn handle_purge(_args: &Args, _data_store: &mut DataStore) {
    // Purge mode - not implemented
}
RUSTEOF

