use crate::calendar::{Appointment, Event, Todo};
use std::collections::HashMap;

pub fn parse_ical(content: &str) -> (Vec<Appointment>, Vec<Event>, Vec<Todo>, usize) {
    let mut appointments = Vec::new();
    let mut events = Vec::new();
    let mut todos = Vec::new();
    let mut skipped = 0;

    let lines: Vec<&str> = content.lines().collect();
    let mut i = 0;

    while i < lines.len() {
        let line = lines[i].trim();

        if line == "BEGIN:VEVENT" {
            let (evt, is_event, success) = parse_vevent(&lines, &mut i);
            if success {
                if is_event {
                    events.push(evt as Event);
                } else {
                    appointments.push(evt as Appointment);
                }
            } else {
                skipped += 1;
            }
        } else if line == "BEGIN:VTODO" {
            if let Some(todo) = parse_vtodo(&lines, &mut i) {
                todos.push(todo);
            } else {
                skipped += 1;
            }
        }

        i += 1;
    }

    (appointments, events, todos, skipped)
}

fn parse_vevent(lines: &[&str], pos: &mut usize) -> (Appointment, bool, bool) {
    let mut dtstart = String::new();
    let mut dtend = String::new();
    let mut duration = String::new();
    let mut summary = String::new();
    let mut is_all_day = false;

    *pos += 1;
    while *pos < lines.len() {
        let line = lines[*pos].trim();

        if line == "END:VEVENT" {
            break;
        }

        if line.starts_with("DTSTART") {
            if line.contains(";VALUE=DATE:") {
                is_all_day = true;
                dtstart = line.split(':').nth(1).unwrap_or("").to_string();
            } else if let Some(val) = line.split(':').nth(1) {
                dtstart = val.to_string();
            }
        } else if line.starts_with("DTEND") {
            dtend = line.split(':').nth(1).unwrap_or("").to_string();
        } else if line.starts_with("DURATION") {
            duration = line.split(':').nth(1).unwrap_or("").to_string();
        } else if line.starts_with("SUMMARY") {
            summary = line.split(':').nth(1).unwrap_or("").to_string();
            // Unescape special characters
            summary = summary.replace("\\,", ",");
            summary = summary.replace("\\n", "\n");
            summary = summary.replace("\\;", ";");
        }

        *pos += 1;
    }

    // Convert dtstart to appointment
    let (date, time) = format_datetime(&dtstart, is_all_day);
    let (end_date, end_time) = if !dtend.is_empty() {
        format_datetime(&dtend, is_all_day)
    } else if !duration.is_empty() {
        calculate_end_time(&dtstart, &duration, is_all_day)
    } else {
        (date.clone(), "00:00".to_string())
    };

    let apt = Appointment {
        date,
        start_time: time,
        end_date,
        end_time,
        title: summary,
    };

    (apt, is_all_day, true)
}

fn parse_vtodo(lines: &[&str], pos: &mut usize) -> Option<Todo> {
    let mut priority = 0;
    let mut summary = String::new();

    *pos += 1;
    while *pos < lines.len() {
        let line = lines[*pos].trim();

        if line == "END:VTODO" {
            break;
        }

        if line.starts_with("PRIORITY") {
            if let Some(val) = line.split(':').nth(1) {
                priority = val.parse().unwrap_or(0);
            }
        } else if line.starts_with("SUMMARY") {
            summary = line.split(':').nth(1).unwrap_or("").to_string();
            summary = summary.replace("\\,", ",");
            summary = summary.replace("\\n", "\n");
            summary = summary.replace("\\;", ";");
        }

        *pos += 1;
    }

    if !summary.is_empty() {
        Some(Todo {
            priority: if priority > 0 { priority } else { 1 },
            title: summary,
            completed: false,
        })
    } else {
        None
    }
}

fn format_datetime(dt: &str, is_all_day: bool) -> (String, String) {
    // dt format: yyyyMMddTHHmmss or yyyyMMdd
    if is_all_day || !dt.contains('T') {
        let year = &dt[0..4];
        let month = &dt[4..6];
        let day = &dt[6..8];
        (format!("{}/{}/{}", month, day, &year[2..]), "00:00".to_string())
    } else {
        let year = &dt[0..4];
        let month = &dt[4..6];
        let day = &dt[6..8];
        let hour = &dt[9..11];
        let min = &dt[11..13];
        (format!("{}/{}/{}", month, day, &year[2..]), format!("{}:{}", hour, min))
    }
}

fn calculate_end_time(dtstart: &str, duration: &str, is_all_day: bool) -> (String, String) {
    // Parse duration like P1DT9H17M0S
    let mut days = 0;
    let mut hours = 0;
    let mut mins = 0;
    let mut secs = 0;

    if let Some(date_part) = duration.split('T').next() {
        if let Some(d_str) = date_part.strip_prefix('P') {
            if let Some(d) = d_str.strip_suffix('D') {
                days = d.parse::<i32>().unwrap_or(0);
            }
        }
    }

    if let Some(time_part) = duration.split('T').nth(1) {
        let mut remaining = time_part;
        if let Some(h_idx) = remaining.find('H') {
            if let Ok(h) = remaining[..h_idx].parse::<i32>() {
                hours = h;
            }
            remaining = &remaining[h_idx + 1..];
        }
        if let Some(m_idx) = remaining.find('M') {
            if let Ok(m) = remaining[..m_idx].parse::<i32>() {
                mins = m;
            }
            remaining = &remaining[m_idx + 1..];
        }
        if let Some(s_idx) = remaining.find('S') {
            if let Ok(s) = remaining[..s_idx].parse::<i32>() {
                secs = s;
            }
        }
    }

    // Calculate end datetime
    let year = &dtstart[0..4];
    let month = &dtstart[4..6];
    let day_str = &dtstart[6..8];
    let hour = if dtstart.len() > 9 { &dtstart[9..11] } else { "00" };
    let min = if dtstart.len() > 11 { &dtstart[11..13] } else { "00" };

    let mut day = day_str.parse::<i32>().unwrap_or(1);
    let mut h = hour.parse::<i32>().unwrap_or(0);
    let mut m = min.parse::<i32>().unwrap_or(0);

    day += days;
    h += hours;
    m += mins;

    if secs >= 30 {
        m += 1;
    }

    if m >= 60 {
        h += m / 60;
        m %= 60;
    }

    if h >= 24 {
        day += h / 24;
        h %= 24;
    }

    // Very simple - assume no month/year overflow for now
    let end_date = if day > 31 {
        // Move to next month/year - simplified
        format!("{}/{}/{}", (month.parse::<i32>().unwrap_or(1) % 12 + 1), 
                day % 31, year)
    } else {
        format!("{}/{}/{}", month, day, &year[2..])
    };

    (end_date, format!("{:02}:{:02}", h, m))
}
