use crate::calendar::{Appointment, Event, Todo};
use crate::args::Args;
use std::fs;
use std::path::PathBuf;
use std::io::Write;

pub struct DataStore {
    data_dir: PathBuf,
    appointments: Vec<Appointment>,
    events: Vec<Event>,
    todos: Vec<Todo>,
}

impl DataStore {
    pub fn new(data_dir: PathBuf) -> Self {
        let mut store = DataStore {
            data_dir: data_dir.clone(),
            appointments: Vec::new(),
            events: Vec::new(),
            todos: Vec::new(),
        };
        store.load();
        store
    }

    fn load(&mut self) {
        // Create directory if it doesn't exist
        let _ = fs::create_dir_all(&self.data_dir);
        let _ = fs::create_dir_all(self.data_dir.join("hooks"));
        let _ = fs::create_dir_all(self.data_dir.join("notes"));

        // Load appointments
        if let Ok(content) = fs::read_to_string(self.data_dir.join("apts")) {
            self.appointments = parse_apts(&content);
        }

        // Load todos
        if let Ok(content) = fs::read_to_string(self.data_dir.join("todo")) {
            self.todos = parse_todos(&content);
        }
    }

    pub fn save(&self) -> std::io::Result<()> {
        let _ = fs::create_dir_all(&self.data_dir);

        // Save appointments
        let apts_path = self.data_dir.join("apts");
        let mut apts_file = fs::File::create(apts_path)?;
        for apt in &self.appointments {
            writeln!(apts_file, "{} @ {} -> {} @ {}|{}", 
                apt.date, apt.start_time, apt.end_date, apt.end_time, apt.title)?;
        }

        // Save todos
        let todo_path = self.data_dir.join("todo");
        let mut todo_file = fs::File::create(todo_path)?;
        for todo in &self.todos {
            writeln!(todo_file, "[{}] {}", todo.priority, todo.title)?;
        }

        // Create empty conf if needed
        let conf_path = self.data_dir.join("conf");
        if !conf_path.exists() {
            fs::File::create(conf_path)?;
        }

        Ok(())
    }

    pub fn add_appointments(&mut self, apts: &[Appointment]) {
        self.appointments.extend(apts.to_vec());
    }

    pub fn add_events(&mut self, events: &[Event]) {
        self.events.extend(events.to_vec());
    }

    pub fn add_todos(&mut self, todos: &[Todo]) {
        self.todos.extend(todos.to_vec());
    }

    pub fn export_ical(&self) {
        println!("BEGIN:VCALENDAR");
        println!("VERSION:2.0");
        println!("PRODID:-//calcurse//NONSGML v4.8.2//EN");

        // Export appointments
        for apt in &self.appointments {
            let duration = calculate_duration_from_strings(&apt.date, &apt.start_time, &apt.end_date, &apt.end_time);
            println!("BEGIN:VEVENT");
            println!("DTSTART:{}", format_iso_datetime(&apt.date, &apt.start_time));
            println!("DURATION:{}", duration);
            let escaped = apt.title.replace(',', "\\,");
            println!("SUMMARY:{}", escaped);
            println!("END:VEVENT");
        }

        // Export todos
        for todo in &self.todos {
            println!("BEGIN:VTODO");
            println!("PRIORITY:{}", todo.priority);
            let escaped = todo.title.replace(',', "\\,");
            println!("SUMMARY:{}", escaped);
            println!("END:VTODO");
        }

        println!("END:VCALENDAR");
    }

    pub fn grep(&self) {
        for apt in &self.appointments {
            println!("{} @ {} -> {} @ {}|{}", 
                apt.date, apt.start_time, apt.end_date, apt.end_time, apt.title);
        }
    }

    pub fn list_todos(&self, args: &Args) {
        if self.todos.is_empty() {
            return;
        }

        println!("to do:");
        let mut count = 1;
        for todo in &self.todos {
            if let Some(priority) = args.todo_priority {
                if todo.priority != priority {
                    continue;
                }
            }
            println!("{}. {}", count, todo.title);
            count += 1;
        }
    }

    pub fn list_day(&self, args: &Args) {
        if let Some(ref day_str) = args.day {
            // Parse day string - could be a date or a number
            if day_str.chars().all(|c| c.is_numeric()) {
                // It's a number of days
                // TODO: implement
            } else {
                // It's a date
                println!("{}:", day_str);
                for apt in &self.appointments {
                    if apt.date == *day_str {
                        println!(" - {} -> {}", apt.start_time, apt.end_time);
                        println!("\t{}", apt.title);
                    }
                }
            }
        }
    }
}

fn parse_apts(content: &str) -> Vec<Appointment> {
    let mut apts = Vec::new();
    for line in content.lines() {
        if let Some(pipe_idx) = line.rfind('|') {
            let title = line[pipe_idx + 1..].to_string();
            let rest = &line[..pipe_idx];
            if let Some(arrow_idx) = rest.find("->") {
                let before = &rest[..arrow_idx].trim();
                let after = &rest[arrow_idx + 2..].trim();

                // Parse "01/01/1980 @ 00:01"
                if let Some(at_idx) = before.rfind('@') {
                    let date = before[..at_idx].trim();
                    let time = before[at_idx + 1..].trim();

                    if let Some(at_idx2) = after.rfind('@') {
                        let end_date = after[..at_idx2].trim();
                        let end_time = after[at_idx2 + 1..].trim();

                        apts.push(Appointment {
                            date: date.to_string(),
                            start_time: time.to_string(),
                            end_date: end_date.to_string(),
                            end_time: end_time.to_string(),
                            title,
                        });
                    }
                }
            }
        }
    }
    apts
}

fn parse_todos(content: &str) -> Vec<Todo> {
    let mut todos = Vec::new();
    for line in content.lines() {
        if let Some(bracket_idx) = line.find(']') {
            if line.starts_with('[') {
                if let Ok(priority) = line[1..bracket_idx].parse() {
                    let title = line[bracket_idx + 1..].trim().to_string();
                    todos.push(Todo {
                        priority,
                        title,
                        completed: false,
                    });
                }
            }
        }
    }
    todos
}

fn calculate_duration_from_strings(start_date: &str, start_time: &str, end_date: &str, end_time: &str) -> String {
    // Parse dates and times: mm/dd/yy hh:mm
    let start_total = date_time_to_secs(start_date, start_time);
    let end_total = date_time_to_secs(end_date, end_time);

    let secs = if end_total >= start_total { 
        end_total - start_total 
    } else { 
        0 
    };

    let days = secs / 86400;
    let remaining = secs % 86400;
    let hours = remaining / 3600;
    let remaining = remaining % 3600;
    let mins = remaining / 60;
    let secs = remaining % 60;

    format!("P{}DT{}H{}M{}S", days, hours, mins, secs)
}

fn date_time_to_secs(date: &str, time: &str) -> i64 {
    // Very simple conversion - just for duration calculation
    let date_parts: Vec<&str> = date.split('/').collect();
    let time_parts: Vec<&str> = time.split(':').collect();

    if date_parts.len() != 3 || time_parts.len() != 2 {
        return 0;
    }

    let month: i64 = date_parts[0].parse().unwrap_or(1);
    let day: i64 = date_parts[1].parse().unwrap_or(1);
    let year: i64 = if date_parts[2].len() == 2 {
        let y: i64 = date_parts[2].parse().unwrap_or(0);
        if y < 50 { 2000 + y } else { 1900 + y }
    } else {
        date_parts[2].parse().unwrap_or(1970)
    };

    let hour: i64 = time_parts[0].parse().unwrap_or(0);
    let min: i64 = time_parts[1].parse().unwrap_or(0);

    // Days since epoch (very simplified)
    let days_in_year = (year - 1970) * 365;
    let days_in_month = month * 31; // Simplified
    let total_days = days_in_year + days_in_month + day;
    let total_secs = total_days * 86400 + hour * 3600 + min * 60;

    total_secs
}

fn format_iso_datetime(date: &str, time: &str) -> String {
    // Convert "mm/dd/yy @ hh:mm" to "yyyyMMddTHHmmss"
    let parts: Vec<&str> = date.split('/').collect();
    if parts.len() == 3 {
        let month = parts[0];
        let day = parts[1];
        let year = if parts[2].len() == 2 {
            let y: i32 = parts[2].parse().unwrap_or(0);
            if y < 50 {
                format!("20{:02}", y)
            } else {
                format!("19{:02}", y)
            }
        } else {
            parts[2].to_string()
        };

        let time_parts: Vec<&str> = time.split(':').collect();
        if time_parts.len() == 2 {
            let hour = time_parts[0];
            let min = time_parts[1];
            return format!("{}{}{}T{}{}00", year, month, day, hour, min);
        }
    }
    String::new()
}
